import * as THREE from 'three';
import {trainAsset} from './depot86.js?v=185';
import {partCategory} from './workshop-core.js?v=112';

const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const TRAIN_INFO136=[
 ['body','Carrocería y ventanas','Protege a los pasajeros y sostiene los elementos del coche. Las ventanas permiten observar el entorno.','En el taller: gira el tren, selecciona paneles y usa el despiece para reconocer su montaje.','Observar uniones, estado de paneles y fijaciones; el ejercicio no evalúa resistencia estructural.'],
 ['cab','Cabina de conducción','Reúne los mandos de tracción, frenado y puertas. El operador regula la marcha y comprueba el estado del tren.','En Conducir: aplica tracción, anticipa el frenado y detente dentro de la zona de estación.','Reconocer indicadores, confirmar la detención y revisar la respuesta de los mandos virtuales.'],
 ['motors','Motores de tracción','Transforman energía eléctrica en par; la transmisión lleva ese esfuerzo a las ruedas. El rotor gira dentro del estator.','En el taller: abre el despiece del motor y usa el banco de giro para distinguir carcasa, rotor y elementos internos.','Identificar conexiones, soporte y ventilación. La velocidad del banco es ilustrativa; no mide potencia ni RPM reales.'],
 ['collectors','Captación de corriente','El patín o escobilla hace contacto con la barra conductora y permite alimentar los equipos de tracción.','Aísla el conjunto en la vista 3D para reconocer patín, soporte, aisladores y protección.','Reconocer desgaste y sujeción como conceptos. No se realizan maniobras sobre instalaciones reales.'],
 ['mechanics','Bogies y rodadura','Los bogies soportan la caja, alojan ejes y ruedas y guían el movimiento. La suspensión limita las vibraciones.','En Misiones: explora la incidencia de rodadura, identifica el conjunto y completa la comprobación del ejercicio.','Observar ruedas, apoyos y elementos de guía. La misión representa una revisión visual, sin presiones ni tolerancias reales.'],
 ['doors','Puertas de pasajeros','Controlan la entrada y salida. La confirmación de cierre permite habilitar la tracción en el ejercicio de conducción.','En Misiones: encuentra el obstáculo, retíralo y comprueba el cierre. En Conducir puedes simular una pérdida de bloqueo.','Reconocer recorrido, obstrucción y señal de bloqueo; comprobar el resultado antes de continuar la simulación.'],
 ['locks','Cerraduras entre coches','Mantienen cerrada la puerta de comunicación entre coches y permiten reconocer manija, alojamiento y fijaciones.','Explora el conjunto en el modelo de Línea 8 y usa el despiece para observar sus piezas.','Inspección visual didáctica de montaje y cierre; no representa el mecanismo interno completo.'],
 ['interior','Interior y mobiliario','Asientos, pasamanos, iluminación y paneles conforman el espacio de viaje y los puntos de apoyo.','Activa Ver interior y cambia de cámara para observar distribución, accesos y circulación de pasajeros.','Identificar fijaciones y elementos de apoyo; el número de figuras visibles representa grupos de pasajeros.'],
 ['roof','Cubierta y ventilación','La cubierta protege los equipos superiores. La ventilación mueve aire para renovar el ambiente interior.','En Misiones: revisa el equipo virtual, restablece la conexión y realiza el ensayo de ventilación.','Reconocer alimentación, conectores y respuesta del ventilador mediante los estados del ejercicio.'],
 ['tracks','Vía y alimentación','La vía sostiene y guía el tren; la alimentación de tracción y los servicios auxiliares cumplen funciones diferentes.','En Observar: cambia de estación y cámara, sigue el tren y comprueba la respuesta al corte de energía.','Reconocer vía, guía, captación y distribución. La vista eléctrica es conceptual y no calcula protecciones ni cortocircuitos.']
].map(([id,name,role,activity,job])=>({id,name,role,activity,job}));

export function motionExample136(kmh,braking){const v=Number(kmh)/3.6,b=Number(braking);return {speed:v,distance:v*v/(2*b),time:v/b};}
export function passengerExample136(queue,load,capacity,dwell,terminal=false){const exiting=terminal?load:Math.floor(load*.2),limit=Math.floor(Math.max(0,dwell-8)*36*.7),entering=Math.max(0,Math.min(Math.floor(queue),capacity-load+exiting,limit));return {exiting,entering,load:load-exiting+entering,queue:queue-entering,limit};}

function diagram(id){
 const symbols={body:'▱',cab:'◉',motors:'↻',collectors:'ϟ',mechanics:'◎',doors:'⇆',locks:'⊞',interior:'▥',roof:'≋',tracks:'═'};
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 300"><rect width="600" height="300" rx="20" fill="#172b3a"/><path d="M55 227H545M70 245H530" stroke="#55778a" stroke-width="6"/><rect x="120" y="85" width="360" height="126" rx="24" fill="#254b60" stroke="#72c4cf" stroke-width="4"/><text x="300" y="167" text-anchor="middle" fill="#e1bb72" font-size="72">${symbols[id]||'↔'}</text><circle cx="175" cy="218" r="17" fill="#a7bec8"/><circle cx="425" cy="218" r="17" fill="#a7bec8"/></svg>`;
}
export function renderTrainInfo136(host){
 host.innerHTML=`<section class="train-info136"><header><span class="eyebrow">APRENDER · EXPLORAR · COMPRENDER</span><h2>Cómo funciona el tren</h2><p>Conoce el trabajo de cada conjunto, los cálculos del simulador y las actividades del taller.</p><p class="info-scope136">Vistas de los modelos 3D y esquemas educativos originales. Las imágenes no son fotografías de equipos reales. Las prácticas son simuladas.</p></header><nav class="info-nav136" aria-label="Secciones de información"><a href="#info-parts136">Partes del tren</a><a href="#info-math136">Cálculos</a><a href="#info-work136">Trabajo en el taller</a></nav><section id="info-parts136"><div class="info-toolbar136"><h3>Parte por parte</h3><label>Modelo de las imágenes <select id="info-model136"><option value="NM22">NM-22 · Línea 1</option><option value="NM79">NM-79 · Línea 8</option><option value="MP82">MP-82 · Línea 8</option></select></label></div><p id="info-images-status136" role="status">Preparando vistas del modelo…</p><div class="info-grid136">${TRAIN_INFO136.map(p=>`<article id="info-${p.id}136" class="info-card136"><div class="info-image136" data-photo="${p.id}">${diagram(p.id)}</div><small data-caption="${p.id}">Esquema educativo · ${esc(p.name)}</small><h4>${esc(p.name)}</h4><p>${esc(p.role)}</p><h5>Qué puedes hacer</h5><p>${esc(p.activity)}</p><h5>Trabajo que realiza / revisión</h5><p>${esc(p.job)}</p></article>`).join('')}</div></section><section id="info-math136" class="info-math136"><h3>Cómo calcula el simulador</h3><p>Estos ejemplos explican las reglas del programa. Sus controles son independientes de la partida.</p><div class="info-grid136"><article class="info-card136"><h4>Velocidad, avance y frenado</h4><p><code>v = km/h ÷ 3.6</code><br><code>Δx = v · Δt</code><br><code>d = v² ÷ (2b)</code><br><code>t = v ÷ b</code></p><p>v en m/s, b en m/s², d en metros y t en segundos. El motor limita la velocidad usando la distancia restante y aplica aceleración o frenado por pasos de tiempo.</p><label>Velocidad (km/h)<input id="info-speed136" type="number" min="0" max="80" value="60"></label><label>Frenado (m/s²)<select id="info-brake136"><option value="1.2">1.2 · escenario L8</option><option value="1.8">1.8 · escenario L1</option><option value="2">2.0 · emergencia</option></select></label><output id="info-stop136" aria-live="polite"></output><p>Ejemplo con frenado constante y sin tiempo de reacción. El escenario usa 80 km/h en L1 y 60 km/h en L8; la lluvia añade una restricción configurable.</p></article><article class="info-card136"><h4>Espera, descenso y embarque</h4><p><code>llegadas = tasa horaria · Δt ÷ 3600</code><br><code>descenso = floor(carga · 0.20)</code><br><code>límite = floor(max(0, parada − 8) · 36 · 0.7)</code></p><p>Suben como máximo las personas en espera, las plazas libres tras el descenso y el límite por parada. En terminal baja toda la carga.</p><label>Personas en espera<input id="info-queue136" type="number" min="0" max="10000" value="300"></label><label>Carga antes del descenso<input id="info-load136" type="number" min="0" max="1200" value="900"></label><label>Parada (segundos)<input id="info-dwell136" type="number" min="0" max="180" value="30"></label><label><input id="info-terminal136" type="checkbox"> Terminal</label><output id="info-board136" aria-live="polite"></output><p>Capacidad del escenario: 1,200. La espera inicial integra tres minutos de llegadas. Las figuras 3D son una representación agrupada.</p></article><article class="info-card136"><h4>Trayecto y separación</h4><p><code>distancia entre paradas = tramo + 150 m</code><br><code>velocidad segura = √(2b · max(0, distancia libre − 180 m))</code></p><p>El motor acumula las longitudes de los tramos para ubicar las paradas. Entre trenes del mismo sentido usa una separación simplificada de 180 m. No es una reproducción de señalización ferroviaria real.</p><h5>Energía y potencia</h5><p>La alimentación conecta o interrumpe la marcha. El simulador no resuelve consumo eléctrico, potencia, corrientes ni recuperación de energía. El giro del motor en el taller es una demostración visual.</p></article></div></section><section id="info-work136" class="info-card136"><h3>El trabajo en el taller</h3><ol><li><b>Reconocer:</b> selecciona el tren y el conjunto; observa su función.</li><li><b>Aislar en el ejercicio:</b> utiliza el mando de aislamiento de la misión.</li><li><b>Inspeccionar:</b> elige la herramienta e identifica la incidencia virtual.</li><li><b>Intervenir:</b> manipula piezas, conexiones u obstáculos según el objetivo de la misión.</li><li><b>Comprobar:</b> realiza el ensayo y revisa el resultado antes de terminar.</li></ol><p>Las misiones incluyen puertas, ventilación, rodadura y circuitos didácticos. No sustituyen instrucciones de trabajo sobre trenes reales.</p><h4>Prueba de bloqueo de puertas en conducción</h4><p>Esta prueba sí actúa sobre la partida: al perderse la confirmación de cierre, se inhibe la tracción y se aplica el freno de servicio.</p><button id="guide-fault-toggle144">Simular pérdida de bloqueo</button><p id="guide-fault-status144" role="status"></p></section></section>`;
 const $=id=>host.querySelector('#'+id),bounded=(id,min,max,fallback)=>{const n=Number($(id).value);return Number.isFinite(n)?Math.min(max,Math.max(min,n)):fallback;};
 function calculate(){const m=motionExample136(bounded('info-speed136',0,80,60),Number($('info-brake136').value));$('info-stop136').textContent=`${m.speed.toFixed(2)} m/s · ${m.distance.toFixed(1)} m de frenado · ${m.time.toFixed(1)} s`;const p=passengerExample136(bounded('info-queue136',0,10000,300),bounded('info-load136',0,1200,900),1200,bounded('info-dwell136',0,180,30),$('info-terminal136').checked);$('info-board136').textContent=`Bajan ${p.exiting} · suben ${p.entering} · carga final ${p.load} · quedan ${p.queue} en espera (límite por parada: ${p.limit}).`;}
 host.querySelectorAll('.info-math136 input,.info-math136 select').forEach(e=>e.addEventListener('input',calculate));calculate();
 let generation=0;
 async function pictures(){const current=++generation,id=$('info-model136').value;try{await renderModelPhotos136(host,id,()=>current===generation);if(current===generation)$('info-images-status136').textContent='Vistas del modelo 3D · los conjuntos ausentes conservan un esquema educativo.';}catch{if(current===generation)$('info-images-status136').textContent='Esquemas educativos disponibles. Las vistas 3D requieren WebGL y el modelo local.';}}
 $('info-model136').onchange=pictures;pictures();
 return {open(part){host.querySelector('#info-'+part+'136')?.scrollIntoView({block:'start',behavior:'smooth'});}};
}

async function renderModelPhotos136(host,id,isCurrent){
 const source=await trainAsset(id);if(!isCurrent())return;source.updateMatrixWorld(true);
 const groups=new Map(TRAIN_INFO136.map(p=>[p.id,new THREE.Group()]));
 source.traverse(o=>{if(!o.isMesh)return;let family=o.userData.familia_visual||'';for(let p=o.parent;!family&&p;p=p.parent)family=p.userData.familia_visual||'';const key=partCategory(o.name,family),copy=new THREE.Mesh(o.geometry,o.material);copy.applyMatrix4(o.matrixWorld);groups.get(key)?.add(copy);});
 const renderer=new THREE.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});
 renderer.setSize(640,360);renderer.setPixelRatio(1);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;
 const scene=new THREE.Scene();scene.background=new THREE.Color('#dce5eb');scene.add(new THREE.HemisphereLight(0xffffff,0x566779,2));const light=new THREE.DirectionalLight(0xffffff,3);light.position.set(5,9,8);scene.add(light);const camera=new THREE.PerspectiveCamera(35,640/360,.01,1000);
 try{for(const [key,group]of groups){await new Promise(resolve=>requestAnimationFrame(resolve));if(!isCurrent())return;const photo=host.querySelector(`[data-photo="${key}"]`),caption=host.querySelector(`[data-caption="${key}"]`);if(!group.children.length){photo.innerHTML=diagram(key);caption.textContent=`Esquema educativo · conjunto sin vista separada en ${id}`;continue;}scene.add(group);const box=new THREE.Box3().setFromObject(group),center=box.getCenter(new THREE.Vector3()),radius=box.getSize(new THREE.Vector3()).length()*.5,distance=Math.max(.5,radius/Math.sin(THREE.MathUtils.degToRad(17.5))*1.12);camera.position.copy(center).add(new THREE.Vector3(.65,.42,.9).normalize().multiplyScalar(distance));camera.lookAt(center);camera.near=Math.max(.005,distance-radius*1.5);camera.far=distance+radius*3+1;camera.updateProjectionMatrix();renderer.render(scene,camera);const img=document.createElement('img');img.src=renderer.domElement.toDataURL('image/webp');img.alt=`Vista del modelo ${id}: ${TRAIN_INFO136.find(p=>p.id===key).name}`;img.width=640;img.height=360;photo.replaceChildren(img);caption.textContent=`Vista del modelo 3D ${id} · geometría educativa aproximada`;scene.remove(group);}}
 finally{renderer.dispose();renderer.forceContextLoss();}
}
